<!doctype html><html><head><style>body{font-family:DejaVu Sans;font-size:10px;color:#172033}h1{font-size:20px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccd5e0;padding:6px}th{background:#edf3f8}.metrics td{font-size:13px;font-weight:bold}</style></head><body><h1>Platform Billing Report</h1><p>{{ $from->format('d M Y') }} to {{ $to->format('d M Y') }}</p><table class="metrics"><tr><td>Invoiced<br>{{ number_format((float)$invoiced,2) }}</td><td>Collected<br>{{ number_format((float)$collected,2) }}</td><td>Refunded<br>{{ number_format((float)$refunded,2) }}</td><td>Credits<br>{{ number_format((float)$credited,2) }}</td><td>Outstanding<br>{{ number_format((float)$outstanding,2) }}</td></tr></table><h2>Invoices</h2><table><tr><th>Invoice</th><th>Clinic</th><th>Due</th><th>Total</th><th>Paid</th><th>Credit</th><th>Refund</th><th>Balance</th><th>Status</th></tr>@foreach($invoices as $i)<tr><td>{{ $i->number }}</td><td>{{ $i->clinic->name }}</td><td>{{ $i->due_date->format('d M Y') }}</td><td>{{ $i->currency }} {{ $i->total }}</td><td>{{ $i->amount_paid }}</td><td>{{ $i->credited_amount }}</td><td>{{ $i->refunded_amount }}</td><td>{{ number_format($i->balance(),2) }}</td><td>{{ strtoupper($i->status) }}</td></tr>@endforeach</table></body></html>
